  `zanrovi` varchar(500) DEFAULT NULL,
  `popunjen` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_ponude`),
  UNIQUE KEY `uk_job_business_date_time_location` (`username_business`,`datum`,`pocetak`,`lokacija`),
  CONSTRAINT `job_offer_ibfk_1` FOREIGN KEY (`username_business`) REFERENCES `business_korisnik` (`username_business`) ON DELETE CASCADE
